import React from "react";
import ReactDOM from "react-dom/client";
import "bootstrap/dist/css/bootstrap.min.css";
import "bootstrap/dist/js/bootstrap.bundle.js";
import "@fortawesome/fontawesome-free/css/all.min.css";
import App from "./App";
import "./index.scss";
import { eInitBreakpoints, eInitTranslation, eLocale } from "react-e-utils";

eInitTranslation(
  [
    await eLocale.fetch("en", "ltr", "English", [], "/local/en.json"),
    await eLocale.fetch("ar", "rtl", "Arabic", [], "/local/ar.json"),
  ],
  {
    fillerTag: "<?>",
    autoDetect: true,
    defaultLocale: "en",
  }
);

eInitBreakpoints();

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<App />);
