import "./App.scss";
import Home from "./pages/Home/Home";
import ContactUs from "./Components/HomePageComponents/ContactUs/ContactUs";
import Layout from "./Components/Layout/Layout";
import Notfound from "./Components/Notfound/Notfound";
import { createHashRouter, RouterProvider } from "react-router-dom";
import FAQ from "./pages/FAQ/FAQ";
import Plans from "./pages/Plans/Plans";
import "./i18next";
import { eCreateMuiTheme, MuiApp } from "react-e-components";
import { MultiProviders } from "react-e-utils";

function App() {
  let routers = createHashRouter([
    {
      path: "/",
      element: <Layout />,
      children: [
        { index: true, element: <Home /> },
        { path: "contact", element: <ContactUs /> },
        { path: "FAQ", element: <FAQ /> },
        { path: "Plans", element: <Plans /> },
        { path: "*", element: <Notfound /> },
      ],
    },
  ]);
  return (
    <MultiProviders
      includeTranslation={true}
      includeBreakpoints={true}
      render={({ locale, dir }) => {
        return (
          <MuiApp
            locale={locale}
            dir={dir}
            theme={eCreateMuiTheme({
              dir: dir,
              primaryColor: "$primary",
            })}
          >
            <RouterProvider router={routers}></RouterProvider>
          </MuiApp>
        );
      }}
    />
  );
}

export default App;
