export default class eNav {
  static copyToClipboard(str, alertText = "Data copied to clipboard") {
    try {
      navigator.clipboard.writeText(str);
      if (alertText) alert(alertText);
    } catch (err) {
      console.trace(this?.constructor?.name, err);
      return undefined;
    }
  }
  static async share({
    title,
    text,
    url,
    files
  }) {
    try {
      await navigator.share({
        title: title,
        // Title of the thing you want to share.
        text: text,
        // Description or more detailed text to share.
        url: url,
        // URL to share.
        files: files // files to share.
      });
    } catch (err) {
      console.trace(this?.constructor?.name, err);
      return undefined;
    }
  }
}
window.eNav = eNav;