import i18next from "i18next";
import { initReactI18next } from "react-i18next";

i18next.use(initReactI18next).init(

  async (err, t) => {
    if (err) {
      console.error("Error initializing i18next:", err);
      return;
    }

    // Fetch translation files
    try {
      const [enResponse, arResponse] = await Promise.all([
        fetch("/local/en.json"),
        fetch("/local/ar.json"),
      ]);

      const enData = await enResponse.json();
      const arData = await arResponse.json();

      // Update resources with fetched data
      i18next.addResourceBundle("en", "translation", enData, true, true);
      i18next.addResourceBundle("ar", "translation", arData, true, true);

      // Set the initial language
      i18next.changeLanguage("en");
    } catch (error) {
      console.error("Error fetching translation files:", error);
    }
  }
);

export default i18next;
